<?php
/**  * Merchandise History Tab  * Shows merchandise and combined transaction types only  */
?>  <div class="merchandise-container">  <h2>Merchandise History</h2>  <p style="color: #6b7280; margin-bottom: 2rem;">  Track merchandise sales and combined transactions (service + merchandise).  </p>  <!-- Filters -->  <form method="GET" class="filters">  <input type="hidden" name="tab" value="merchandise_history">  <div class="filters-grid">  <div class="form-group">  <label for="filter_category">Category</label>  <input type="text" name="category" id="filter_category"  value="<?= htmlspecialchars($_GET['category'] ?? '') ?>"  placeholder="Search category">  </div>  <div class="form-group">  <label for="filter_product">Product</label>  <input type="text" name="product" id="filter_product"  value="<?= htmlspecialchars($_GET['product'] ?? '') ?>"  placeholder="Search product">  </div>  <div class="form-group">  <label for="filter_date_from">Date From</label>  <input type="date" name="date_from" id="filter_date_from"  value="<?= htmlspecialchars($_GET['date_from'] ?? '') ?>">  </div>  <div class="form-group">  <label for="filter_date_to">Date To</label>  <input type="date" name="date_to" id="filter_date_to"  value="<?= htmlspecialchars($_GET['date_to'] ?? '') ?>">  </div>  </div>  <div style="display: flex; gap: 1rem; margin-top: 1rem;">  <button type="submit" class="btn btn-primary">Apply Filters</button>  <a href="?tab=merchandise_history" class="btn btn-secondary">Clear Filters</a>  </div>  </form>  <!-- Merchandise Table -->  <table class="data-table">  <thead>  <tr>  <th>Transaction ID</th>  <th>Customer</th>  <th>Products</th>  <th>Total Amount</th>  <th>Date Released</th>  </tr>  </thead>  <tbody>  <?php if (empty($merchandise_history)): ?>  <tr>  <td colspan="5" style="text-align: center; padding: 2rem; color: #6b7280;">  No merchandise transactions found  </td>  </tr>  <?php else: ?>  <?php foreach ($merchandise_history as $merch): ?>  <tr>  <td>  <strong><?= htmlspecialchars($merch['transaction_id']) ?></strong>  </td>  <td><?= htmlspecialchars($merch['customer_name']) ?></td>  <td>  <?php if (!empty($merch['items'])): ?>  <details>  <summary style="cursor: pointer; color: #2563eb;">  <?= count($merch['items']) ?> item(s) - Click to view  </summary>  <div style="margin-top: 0.5rem; padding-left: 1rem;">  <?php foreach ($merch['items'] as $item): ?>  <div style="margin-bottom: 0.25rem;">  <strong><?= htmlspecialchars($item['product_name']) ?></strong>  - Qty: <?= (int)$item['quantity'] ?>  @ ₱<?= number_format($item['unit_price'], 2) ?>  = ₱<?= number_format($item['total_price'], 2) ?>  </div>  <?php endforeach; ?>  </div>  </details>  <?php else: ?>  <span style="color: #9ca3af;">No items</span>  <?php endif; ?>  </td>  <td>₱<?= number_format($merch['total_amount'], 2) ?></td>  <td><?= date('M d, Y g:i A', strtotime($merch['date_released'])) ?></td>  </tr>  <?php endforeach; ?>  <?php endif; ?>  </tbody>  </table>  <!-- Pagination -->  <?php if ($total_pages > 1): ?>  <div class="pagination">  <?php if ($page > 1): ?>  <a href="?tab=merchandise_history&page=<?= $page - 1 ?>">  Previous  </a>  <?php endif; ?>  <?php for ($i = 1; $i <= $total_pages; $i++): ?>  <?php if ($i == $page): ?>  <span class="active"><?= $i ?></span>  <?php else: ?>  <a href="?tab=merchandise_history&page=<?= $i ?>">  <?= $i ?>  </a>  <?php endif; ?>  <?php endfor; ?>  <?php if ($page < $total_pages): ?>  <a href="?tab=merchandise_history&page=<?= $page + 1 ?>">  Next  </a>  <?php endif; ?>  </div>  <?php endif; ?>
</div>
